INSERT INTO "blog_posts" ("id", "country_slug", "post_index", "country", "country_code", "state", "title", "subtitle", "header", "description", "excerpt", "background_image", "tips_cta_copy", "tips_slug", "status", "published_at", "created_at") VALUES ($s$88d35806-7dd9-43df-8d28-2b17ca69980d$s$, $s$united-states-new-york$s$, 2, $s$United States$s$, $s$US$s$, $s$New York$s$, $s$📍4th of July fireworks Over the Hudson$s$, $s$✨A Night of Stars & Stripes: Catching the 4th of July Fireworks on the Hudson River🎇$s$, $s$📍A 4th of July NYC Spectacle$s$, $s$Oh, that 4th of July night on the Hudson River! It's one of those experiences you don't forget.  I'm taking you back to the sheer magic of watching those spectacular fireworks light up the New York City skyline. From the buzzing energy of the crowds to finding that perfect spot to witness the display, I'll share all the highlights of what truly felt like a quintessential NYC summer moment. I love fireworks so much, and this display was everything!$s$, $s$4th of July Spectacle: Fireworks on the Hudson! 🎆🗽🇺🇸$s$, $s$aroundtheworld50s/blog/united-states-new-york/2/IMG_1138$s$, NULL, NULL, $s$published$s$, '2025-08-16T00:00:00.000Z'::timestamptz, '2025-08-16T00:00:00.000Z'::timestamptz);
INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$88d35806-7dd9-43df-8d28-2b17ca69980d$s$, 0, $s$text$s$, $s${"html":"The anticipation was absolutely palpable. We arrived in the area around 5 PM, determined to snag a great spot along the Lower East Side. It took us more than 30 minutes just to walk from the station because so many streets were closed! We had to follow the police directions to figure out where we were even allowed to enter the viewing area. Even by 5 PM, people were already stretched out along the river, totally committed to getting the best view. Despite the crowds, we managed to find a good spot, even able to lean right on the railing! The riverfront slowly filled up, everyone eager to witness the legendary Macy's fireworks display.\n\nAnd then, just like that, it began. A full-on symphony of color just erupted over the river, painting the entire night sky. The fireworks display was breathtaking, dazzling against the iconic city skyline. I remember just being completely in awe as each explosion arced across the sky, reflecting perfectly in the waters of the Hudson below. It truly felt like the city itself was part of the show, not just a backdrop.\n\nFor me, that display was more than just pretty lights; it was a powerful reminder of why I love New York City so much – that incredible sense of power and celebration. It captures the spirit of Independence Day in such a unique way.\n\n💥Pro Tip: If you ever go, arrive early! Seriously, securing a good spot along the riverfront is key to truly soaking in the show without any obstructions.\n\nHave you ever witnessed the Macy's 4th of July Fireworks display? What was your favorite part? Share your experience in the comments below!"}$s$::jsonb),
  ($s$88d35806-7dd9-43df-8d28-2b17ca69980d$s$, 1, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-new-york/2/IMG_2288","aroundtheworld50s/blog/united-states-new-york/2/IMG_2287","aroundtheworld50s/blog/united-states-new-york/2/IMG_2286","aroundtheworld50s/blog/united-states-new-york/2/IMG_2285","aroundtheworld50s/blog/united-states-new-york/2/IMG_2284","aroundtheworld50s/blog/united-states-new-york/2/IMG_0786","aroundtheworld50s/blog/united-states-new-york/2/IMG_1136","aroundtheworld50s/blog/united-states-new-york/2/IMG_1137","aroundtheworld50s/blog/united-states-new-york/2/IMG_1138","aroundtheworld50s/blog/united-states-new-york/2/IMG_1132","aroundtheworld50s/blog/united-states-new-york/2/IMG_1135"]}$s$::jsonb);
